126	impl Memory {
127	    pub fn remember(&mut self, req: &Remember) -> Result<WriteOutcome> {
128	        let now = now();
129	        let c: Clean = guard::check(req, &self.settings, parse_unix(&now).unwrap_or(0))?;
130	        let tx = self.write_tx()?;
131	
132	        let (subject, subject_norm) = match &c.subject {
133	            Some(s) => {
134	                let norm = resolve_alias(&tx, &c.ns, &normalize_name(s))?;
135	                (Some(ensure_subject(&tx, &c.ns, s, &norm)?), norm)
136	            }
137	            None => (None, String::new()),
138	        };
139	        for alias in &c.aliases {
140	            let a = normalize_name(alias);
141	            if a != subject_norm {
142	                tx.execute(
143	                    "INSERT INTO subject_aliases (ns, alias, norm) VALUES (?1, ?2, ?3) \
144	                     ON CONFLICT (ns, alias) DO UPDATE SET norm = excluded.norm",
145	                    params![c.ns, a, subject_norm],
146	                )?;
147	            }
148	        }
149	
150	        let fresh = MemoryRow {
151	            id: new_id(),
152	            ns: c.ns.clone(),
153	            kind: c.kind,
154	            subject,
155	            key: c.key.clone(),
156	            text: c.text.clone(),
157	            tags: c.tags.clone(),
158	            importance: c.importance,
159	            confidence: c.confidence,
160	            source: c.source.clone(),
161	            refs: c.refs.clone(),
162	            pinned: c.pinned,
163	            created_at: now.clone(),
164	            updated_at: now.clone(),
165	            valid_from: now.clone(),
166	            valid_to: None,
167	            superseded_by: None,
168	            expires_at: c.expires_at.clone(),
169	            deleted_at: None,
170	            recall_count: 0,
171	            last_recalled_at: None,
172	        };
173	        let words = word_set(&c.text);
174	
175	        let outcome = if let Some(key) = &c.key {
176	            let current: Option<MemoryRow> = tx
177	                .prepare_cached(&format!(
178	                    "SELECT {COLUMNS} FROM memories WHERE ns = ?1 AND subject_norm = ?2 AND key = ?3 \
179	                     AND valid_to IS NULL AND deleted_at IS NULL"
180	                ))?
181	                .query_row(params![c.ns, subject_norm, key], row)
182	                .optional()?;
183	            match current {
184	                Some(old) if jaccard(&word_set(&old.text), &words) >= 1.0 && old.kind == c.kind => {
185	                    let merged = merge(&tx, &old, &c, req, &now)?;
186	                    WriteOutcome {
187	                        status: WriteStatus::Duplicate,
188	                        memory: merged,
189	                        replaced: None,
190	                        related: vec![],
191	                    }
192	                }
193	                Some(mut old) => {
194	                    tx.execute(
195	                        "UPDATE memories SET valid_to = ?2, superseded_by = ?3 WHERE id = ?1",
196	                        params![old.id, now, fresh.id],
197	                    )?;
198	                    old.valid_to = Some(now.clone());
199	                    old.superseded_by = Some(fresh.id.clone());
200	                    insert_row(&tx, &fresh)?;
201	                    log(
202	                        &tx,
203	                        "supersede",
204	                        Some(&fresh.id),
205	                        &serde_json::json!({"memory": fresh, "replaced": old.id}),
206	                    )?;
207	                    WriteOutcome {
208	                        status: WriteStatus::Replaced,
209	                        memory: fresh,
210	                        replaced: Some(old),
211	                        related: vec![],
212	                    }
213	                }
214	                None => {
215	                    insert_row(&tx, &fresh)?;
216	                    log(&tx, "remember", Some(&fresh.id), &serde_json::to_value(&fresh)?)?;
217	                    WriteOutcome {
218	                        status: WriteStatus::Created,
219	                        memory: fresh,
220	                        replaced: None,
221	                        related: vec![],
222	                    }
223	                }
224	            }
225	        } else {
226	            let mut similar: Vec<(f64, MemoryRow)> =
227	                similar(&tx, &c.ns, c.subject.as_ref().map(|_| subject_norm.as_str()), &c.text)?
228	                    .into_iter()
229	                    .map(|m| (jaccard(&word_set(&m.text), &words), m))
230	                    .collect();
231	            similar.sort_by(|a, b| b.0.total_cmp(&a.0));
232	            match similar.first() {
233	                Some((score, best)) if *score >= DUPLICATE && best.key.is_none() => {
234	                    let merged = merge(&tx, best, &c, req, &now)?;
235	                    WriteOutcome {
236	                        status: WriteStatus::Duplicate,
237	                        memory: merged,
238	                        replaced: None,
239	                        related: vec![],
240	                    }
241	                }
242	                _ => {
243	                    insert_row(&tx, &fresh)?;
244	                    log(&tx, "remember", Some(&fresh.id), &serde_json::to_value(&fresh)?)?;
